// ─── File: api/AccountApi.ts ───  (API helper layer: fast preconditions)
import { APIRequestContext } from '@playwright/test';

export class AccountApi {
  constructor(private request: APIRequestContext) {}

  // Seed an account directly via backend — faster/stabler than UI setup.
  async createAccount(id: string, balance: string) {
    const res = await this.request.post('/api/v1/accounts', {
      data: { id, balance },
    });
    if (!res.ok()) throw new Error(`seed failed: ${res.status()}`);
  }

  // Verify a UI action at the API level (source of truth).
  async getBalance(id: string): Promise<string> {
    const res = await this.request.get(`/api/v1/accounts/${id}/balance`);
    return (await res.json()).balance;
  }
}
