import { test as base } from '@playwright/test';
import { TransferPage } from '../pages/TransferPage';
import { AccountApi } from '../api/AccountApi';

type Fixtures = {
  transferPage: TransferPage;
  accountApi: AccountApi;
  seededAccounts: { from: string; to: string };
};

export const test = base.extend<Fixtures>({
  transferPage: async ({ page }, use) => { await use(new TransferPage(page)); },
  accountApi: async ({ request }, use) => { await use(new AccountApi(request)); },
  // Seed isolated data per test via API, then clean up (teardown after use).
  seededAccounts: async ({ accountApi }, use) => {
    await accountApi.createAccount('SAV2001', '1000000');
    await accountApi.createAccount('CUR3001', '250000');
    await use({ from: 'SAV2001', to: 'CUR3001' });
  },
});
export { expect } from '@playwright/test';
