test('transfer updates balance (verified via API)', async ({ transferPage, accountApi, seededAccounts }) => {
  await transferPage.goto();
  await transferPage.makeTransfer(seededAccounts.from, seededAccounts.to, '50000');

  await expect(async () => {
    const balance = await accountApi.getBalance(seededAccounts.from);
    expect(balance).toBe('950000');     // API-level verification
  }).toPass();
});
